 EXECUTE $source_4$CREATE OR REPLACE FUNCTION mission_creation_owner.preflight_document_v2(p_document jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare errors jsonb:='[]'::jsonb;checks jsonb:='[]'::jsonb;maps jsonb:='[]'::jsonb;
 adoption jsonb;adoption_cache jsonb:='{}'::jsonb;
 s jsonb;a jsonb;actor jsonb;code text;detail text;base_ok boolean:=true;combat_actor boolean;need_default boolean;
 default_key constant text:='mission_map_bind_3ac00867783c8910b81a43b61015ce0b';
begin
 perform mission_ai_board_owner.staff_only();
 PERFORM 1 FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR SHARE;
 PERFORM 1 FROM mission_narrative_internal.runtime_policy WHERE singleton FOR SHARE;
 begin
  perform mission_creation_owner.map_binding_preflight_mission_publish_v1(p_document);
  perform mission_creation_owner.validate_document(p_document);
  checks:=checks||jsonb_build_array(jsonb_build_object('code','document_graph','ok',true));
 exception when others then
  get stacked diagnostics code=returned_sqlstate,detail=message_text;base_ok:=false;
  errors:=errors||jsonb_build_array(jsonb_build_object('code','document_graph','sqlstate',code,'detail',detail));
 end;
 need_default:=base_ok and exists(select 1 from jsonb_array_elements(p_document#>'{plan,definition,scenes}') sc(scene)
  where jsonb_array_length(coalesce(sc.scene->'encounters','[]'::jsonb))>0
   and not exists(select 1 from jsonb_array_elements(p_document->'arenas') ar(arena) where ar.arena->>'step_key'=sc.scene->>'step_key'));
 if need_default then
  if not mission_creation_owner.map_binding_global_default_ready_v1(default_key,1)
   or mission_creation_owner.general_catalog_capacity(default_key,1)<16
   or mission_creation_owner.general_catalog_errors(default_key,1)<>'[]'::jsonb
  then errors:=errors||jsonb_build_array(jsonb_build_object('code','default_map_not_ready'));
  else checks:=checks||jsonb_build_array(jsonb_build_object('code','default_map_ready','ok',true));end if;
 end if;
 if base_ok then
  for s in select value from jsonb_array_elements(p_document#>'{plan,definition,scenes}') loop
   if jsonb_array_length(coalesce(s->'encounters','[]'::jsonb))>0 then
    if jsonb_array_length(coalesce(s#>'{encounters,0,actors}','[]'::jsonb))>12
    then errors:=errors||jsonb_build_array(jsonb_build_object('code','png_roster_limit','step_key',s->>'step_key'));end if;
    a:=null;
    select value into a from jsonb_array_elements(p_document->'arenas') where value->>'step_key'=s->>'step_key';
    if a is null then maps:=maps||jsonb_build_array(jsonb_build_object('step_key',s->>'step_key','origin','default',
      'template_key',default_key,'template_version',1,'zone_key','arena'));
    else maps:=maps||jsonb_build_array(jsonb_build_object('step_key',s->>'step_key','origin','mission_phase',
      'template_key',a->>'template_key','template_version',(a->>'template_version')::integer,'zone_key',a->>'zone_key'));end if;
   end if;
  end loop;
  for actor in select distinct x.actor from jsonb_array_elements(p_document#>'{plan,definition,scenes}') sc(scene)
   cross join lateral jsonb_array_elements(sc.scene->'actors') x(actor) loop
   combat_actor:=exists(select 1 from jsonb_array_elements(p_document#>'{plan,definition,scenes}') cs(scene)
    cross join lateral jsonb_array_elements(coalesce(cs.scene->'encounters','[]'::jsonb)) ce(encounter)
    cross join lateral jsonb_array_elements(coalesce(ce.encounter->'actors','[]'::jsonb)) ca(actor_ref)
    where ca.actor_ref->>'actor_key'=actor->>'actor_key');
   adoption:=NULL;
   IF actor->>'narrative_version_id' IS NOT NULL THEN
    IF NOT(adoption_cache ? (actor->>'narrative_version_id')) THEN
     adoption_cache:=adoption_cache||jsonb_build_object(actor->>'narrative_version_id',
      coalesce(ninja_book_internal.staff_legacy_media_adoption_v1((actor->>'narrative_version_id')::uuid),'null'::jsonb));
    END IF;
    adoption:=nullif(adoption_cache->(actor->>'narrative_version_id'),'null'::jsonb);
   END IF;
   if actor->>'narrative_version_id' is null or not exists(select 1 from public.nb_template_versions v
      where v.id=(actor->>'narrative_version_id')::uuid and v.review_state='approved')
   then errors:=errors||jsonb_build_array(jsonb_build_object('code','png_narrative_not_approved','actor_key',actor->>'actor_key'));end if;
   if combat_actor and (actor->>'mechanical_binding_id' is null or not exists(select 1 from public.nb_mechanical_bindings b
      where b.id=(actor->>'mechanical_binding_id')::uuid and (b.active OR (adoption IS NOT NULL AND adoption->>'binding_id'=b.id::text)) and b.lifecycle_state='approved'
       and b.narrative_version_id=(actor->>'narrative_version_id')::uuid
       and b.narrative_template_id=(actor->>'narrative_template_id')::uuid))
   then errors:=errors||jsonb_build_array(jsonb_build_object('code','png_mechanical_not_approved','actor_key',actor->>'actor_key'));end if;
   if actor->>'narrative_version_id' is not null and adoption IS NULL and not exists(select 1
      from public.nb_template_versions v join public.nb_templates t on t.id=v.template_id and t.current_version_id=v.id
      join public.nb_template_media_versions mv on mv.template_version_id=v.id and mv.template_id=v.template_id
      join storage.objects o on o.bucket_id=mv.bucket and o.name=mv.object_path
      where v.id=(actor->>'narrative_version_id')::uuid and v.template_id=(actor->>'narrative_template_id')::uuid
       and v.review_state='approved' and t.lifecycle_state='approved' and mv.active and mv.lifecycle_state='approved'
       and mv.kind='canonical_full_body' and mv.superseded_by_media_id is null and mv.sha256=mv.verified_sha256
       and o.metadata->>'mimetype'=mv.mime_type and (o.metadata->>'size')::bigint=mv.bytes)
   then errors:=errors||jsonb_build_array(jsonb_build_object('code','png_media_not_approved','actor_key',actor->>'actor_key'));end if;
  end loop;
 end if;
 return jsonb_build_object('schema_version','mission-creation-preflight/2','ok',jsonb_array_length(errors)=0,
  'map_resolution',maps,'checks',checks,'errors',errors,'warnings','[]'::jsonb,
  'limits',jsonb_build_object('pg_max',4,'png_max',12,'map_max_m',50,'actor_radius_m',0.5));
end $function$
